const input = $json.body ?? $json;

if (!input || typeof input.action_id !== 'string' || !input.action_id.trim() || typeof input.action_type !== 'string' || !input.action_type.trim() || input.action_type.length > 100 || typeof input.incident?.id !== 'string' || !input.incident.id.trim() || input.incident.status !== 'RESPONDING' || (input.note != null && (typeof input.note !== 'string' || input.note.length > 500))) {
  return [{
    json: {
      ok: false,
      error: 'Invalid ShaktiOS action payload',
      received_at: new Date().toISOString(),
    },
  }];
}

return [{
  json: {
    ok: true,
    status: 'accepted',
    action_id: input.action_id,
    action_type: input.action_type,
    incident_id: input.incident.id,
    incident_location: input.incident.location,
    incident_severity: input.incident.severity,
    note: input.note ?? null,
    received_at: new Date().toISOString(),
    message: 'Human-approved action received by n8n. Connect your notification node after this step.',
  },
}];
